class Solution {
public:
    vector<int> findIntersectionValues(vector<int>& nums1, vector<int>& nums2) {
        unordered_set<int> s1(nums1.begin(), nums1.end());
        unordered_set<int> s2(nums2.begin(), nums2.end());
        int c1 = 0, c2 = 0;
        for (int x : nums1) if (s2.count(x)) c1++;
        for (int x : nums2) if (s1.count(x)) c2++;
        return {c1, c2};
    }
};

class Solution {
    public int[] findIntersectionValues(int[] nums1, int[] nums2) {
        Set<Integer> s1 = new HashSet<>();
        Set<Integer> s2 = new HashSet<>();
        for (int x : nums1) s1.add(x);
        for (int x : nums2) s2.add(x);
        int c1 = 0, c2 = 0;
        for (int x : nums1) if (s2.contains(x)) c1++;
        for (int x : nums2) if (s1.contains(x)) c2++;
        return new int[]{c1, c2};
    }
}

/**
 * @param {number[]} nums1
 * @param {number[]} nums2
 * @return {number[]}
 */
var findIntersectionValues = function(nums1, nums2) {
    const s1 = new Set(nums1);
    const s2 = new Set(nums2);
    let c1 = 0, c2 = 0;
    for (const x of nums1) if (s2.has(x)) c1++;
    for (const x of nums2) if (s1.has(x)) c2++;
    return [c1, c2];
};
